int kvm_pit_read(struct kvm_io_device *this, gpa_t addr, int len, void *data)
{
    struct kvm_pit *pit = this->opaque;
    int ret = -EOPNOTSUPP;

    if (addr >= KVM_PIT_BASE_ADDRESS && addr < KVM_PIT_BASE_ADDRESS + 4) {
        mutex_lock(&pit->lock);

        if (len == 1)
            *(uint8_t *)data = 0;
        else if (len == 2)
            *(uint16_t *)data = 0;
        else
            *(uint32_t *)data = 0;

        ret = 0;

        mutex_unlock(&pit->lock);
    }

    return ret;
}

int kvm_pit_read(struct kvm_io_device *this, gpa_t addr, int len, void *data)
{
    struct kvm_pit *pit = this->private;
    int ret = 0;

    if (addr >= KVM_PIT_BASE_ADDRESS &&
        addr < KVM_PIT_BASE_ADDRESS + KVM_PIT_NUM_PORTS) {
        mutex_lock(&pit->pit_mutex);
        switch (addr - KVM_PIT_BASE_ADDRESS) {
        case 0: /* Channel 0 */
            *(u8 *)data = pit->channels[0].data;
            break;
        case 1: /* Channel 1 */
            *(u8 *)data = pit->channels[1].data;
            break;
        case 2: /* Channel 2 */
            *(u8 *)data = pit->channels[2].data;
            break;
        case 3: /* Command register */
            *(u8 *)data = pit->command;
            break;
        default:
            ret = -EOPNOTSUPP;
            break;
        }
        mutex_unlock(&pit->pit_mutex);
    } else {
        ret = -EOPNOTSUPP;
    }

    return ret;
}

int kvm_pit_read(struct kvm_io_device *this, gpa_t addr, int len, void *data)
{
    if (addr >= 0x40 && addr < 0x48) {
        unsigned int port = addr - 0x40;
        int channel = port / 2;
        unsigned int val = 0;

        mutex_lock(&pit_mutex);

        if (port % 2 == 0) {
            // Read command/counter
            val = pit_read_counter(channel);
        } else {
            // Read status
            val = pit_read_status(channel);
        }

        mutex_unlock(&pit_mutex);

        switch (len) {
        case 1:
            *(uint8_t *)data = val & 0xFF;
            break;
        case 2:
            *(uint16_t *)data = val & 0xFFFF;
            break;
        default:
            return -EOPNOTSUPP;
        }

        return 0;
    }

    return -EOPNOTSUPP;
}

int kvm_pit_read(struct kvm_io_device *this, gpa_t addr, int len, void *data)
{
    if (addr < 0x40 || addr > 0x50)
        return -EOPNOTSUPP;

    mutex_lock(&pit_mutex);
    switch (addr) {
    case 0x40:
        *(uint8_t *)data = pit_channel_0_read();
        break;
    case 0x41:
        *(uint8_t *)data = pit_channel_1_read();
        break;
    case 0x42:
        *(uint8_t *)data = pit_channel_2_read();
        break;
    default:
        mutex_unlock(&pit_mutex);
        return -EOPNOTSUPP;
    }
    mutex_unlock(&pit_mutex);

    return 0;
}

int kvm_pit_read(struct kvm_io_device *this, gpa_t addr, int len, void *data)
{
    int ret = -EOPNOTSUPP;

    if (addr < 0x40 || addr > 0x43)
        return ret;

    mutex_lock(&pit_mutex);

    switch (addr) {
    case 0x40:
    case 0x41:
    case 0x42:
        /* Read from PIT channels */
        *(u8 *)data = read_pit_channel(addr - 0x40);
        ret = 0;
        break;
    case 0x43:
        /* Read from PIT command register */
        *(u8 *)data = read_pit_command();
        ret = 0;
        break;
    }

    mutex_unlock(&pit_mutex);
    return ret;
}
